const items = $input.all();
const calibrationHistory = items
  .filter(i => i.json && i.json.krish_rating !== undefined && i.json.krish_rating !== null)
  .map(i => i.json);
return [{ json: { calibrationHistory: calibrationHistory } }];

let weeklyGoals = [];
try {
  const goalsItem = $('Read Weekly Goals').first();
  if (goalsItem && goalsItem.json && Array.isArray(goalsItem.json)) {
    weeklyGoals = goalsItem.json;
  } else if (goalsItem && goalsItem.json && goalsItem.json.data) {
    weeklyGoals = goalsItem.json.data;
  } else if (goalsItem && Array.isArray(goalsItem.json)) {
    weeklyGoals = goalsItem.json;
  }
} catch (e) {}
const items = $input.all();
let na = [];
let calibrationContext = '';
try {
  const naRow = items.find(i => i.json.value && Array.isArray(i.json.value));
  if (naRow) na = naRow.json.value;
} catch(e) {}
try {
  const calItem = $('Guarantee Calibration Item').first();
  const rated = calItem ? (calItem.json.calibrationHistory || []) : [];
  if (rated.length > 0) {
    calibrationContext = 'Previous signals Krish rated useful: ' + JSON.stringify(rated.filter(i => i.krish_rating >= 4).map(i => ({ company: i.company_name, type: i.signal_type, note: i.rating_notes })).slice(0, 10)) + ' Previously rated poor: ' + JSON.stringify(rated.filter(i => i.krish_rating <= 2).map(i => ({ company: i.company_name, type: i.signal_type, note: i.rating_notes })).slice(0, 5));
  }
} catch(e) {}
return [{ json: {
  active_goals: weeklyGoals,
  namedAccounts: na,
  calibrationContext: calibrationContext,
  hasCalibration: calibrationContext.length > 0,
  osContext: {
    mindmaker: { icp: 'Enterprise/mid-market C-suite at legacy businesses (finance, healthcare, logistics, insurance, media), 500-5000+ employees', triggerTitles: ['Chief AI Officer','Head of AI Transformation','Chief Digital Officer','CTO','VP Engineering'], triggerEvents: ['new CAIO/CDO/CTO hire','board AI mandate','AI task force formed','stalled AI implementation','budget allocated for AI enablement'] },
    personalBrand: { windows: ['major AI framework release','adtech identity shift','tier-1 conference call for speakers (Cannes Lions, DMEXCO, Programmatic I/O, AI Summit NY)','publisher ad revenue decline story','open podcast guest submissions for AI/media/GTM shows'] }
  },
  sweep_started: new Date().toISOString(),
  ready: true,
  identity_prepend: $('Build Identity Prepend').first().json.identity_prepend
} }];

const items=$input.all();
let na=[];
try{const pc=$('Prepare Context').first();na=pc?(pc.json.namedAccounts||[]).map(function(a){return String(a).toLowerCase();}):[];}catch(e){}
// 2026-07-10 portfolio overhaul: advisory sales retired (Felix inactive).
// buyer/adtech/transformation signals are now MARKET INTEL routed to marcus
// (they feed the content engine's shifts register), never a leads write.
// AdFixus + Meliora ventures are retired: their items are marked non-signals
// so they die at the confirmed-signal gates without touching the topology.
const rm={'buyer-signal':'marcus','adtech-signal':'marcus','transformation-signal':'marcus','content-window':'cleo','visibility-window':'nova','guest-signal':'nell','market-intel':'marcus'};
const deadVentures=['adfixus','meliora'];
return items.map(function(item){
  const d=item.json;
  const co=String(d.company_name||'').trim();
  const sd=String(d.specific_decision||d.summary||'').toLowerCase();
  const conf=String(d.confidence||'low').toLowerCase();
  // Base score: trust the parser's confidence-derived signal_score; else derive.
  let s=Number(d.signal_score)||0;
  if(!s){s=conf==='high'?8:conf==='medium'?5:2;}
  if(co&&na.indexOf(co.toLowerCase())!==-1)s+=2;       // named-account bonus
  if(!co)s-=4;                                          // require a company
  // Recency: a BONUS only, never an age cliff (the old cliff nuked every real
  // signal to -10 when publishedAt was missing). Accept either field name.
  const pub=d.publishedAt||d.source_published_at||null;
  let ah=null; if(pub){try{ah=(Date.now()-new Date(pub).getTime())/3600000;}catch(e){}}
  if(ah!==null&&ah<=72)s+=1;
  s=Math.max(0,Math.min(10,s));
  const st=String(d.signal_type||d.signal_type_candidate||'market-intel');
  const venture=String(d.venture||'').toLowerCase();
  const retired=deadVentures.indexOf(venture)!==-1;
  // description is NOT NULL in zara_signals -> guarantee a non-empty value.
  const why=String(d.why_it_matters||d.specific_decision||d.summary||(co?co+' AI leadership signal':'market signal')).trim();
  return {json:{
    title:String(d.title||d.source_title||''),
    url:String(d.url||d.source_url||''),
    venture:String(d.venture||''),
    company_name:co||null,
    specific_decision:d.specific_decision||null,
    why_it_matters:why,
    summary:String(d.summary||why),
    publishedAt:pub,
    source:String(d.source||''),
    confidence:conf,
    is_signal:d.is_signal===true&&!retired,
    signal_score:retired?0:s,
    signal_type:st,
    routed_to:String(rm[st]||'marcus'),
  }};
});

const prepCtx = $('Prepare Context').first() ? $('Prepare Context').first().json : {};
const activeGoals = prepCtx.active_goals || [];
const identityPrepend = prepCtx.identity_prepend || '';
const goalsText = activeGoals.length > 0 ? "Krish's ACTIVE WEEKLY GOALS (CRITICAL - prioritize signals that serve these!): " + JSON.stringify(activeGoals) : "No active goals this week.";
const prev=$('Perplexity Signal Filter Loop').item.json;const venture=String(prev.venture||'');const stc=String(prev.signal_type_candidate||'');const ventureContext={mindmaker:{accept:'A named enterprise (500+ employees, legacy sector: finance, healthcare, logistics, insurance, media) making a specific C-suite AI leadership move, OR a highly anomalous/strange/funny AI failure at a major company.',reject:'Reject if: startup under $10M funding, junior AI engineering hire, generic we-use-AI PR, consumer AI app launch, government/policy news, unless it is bizarre or hilarious.'},'personal-brand':{accept:'EITHER (A) A specific named conference or podcast with an open call for speakers OR (B) A funny, strange, inspiring, or unexpectedly positive AI story/mistake that can be used for content.',reject:'Reject if: dry technical update, boring B2B press release, obvious "AI is changing the world" fluff.'}};const ctx=ventureContext[venture]||ventureContext['personal-brand'];const userMsg= identityPrepend + '
' + goalsText + '

Title: '+String(prev.title||'')+'
Snippet: '+String(prev.snippet||'')+'
URL: '+String(prev.url||'')+'
Venture context: '+venture+'

Accept criteria: '+ctx.accept+'

Reject criteria: '+ctx.reject+'

Respond in this exact JSON format only, no markdown:
{"is_signal":true,"company_name":"string or null","specific_decision":"string or null","why_it_matters":"string or null","confidence":"high|medium|low","goal_id":"string matching a goal id or null"}

If is_signal is false, all other fields must be null.';return [{json:{userMsg:userMsg,venture:venture,title:prev.title,url:prev.url,snippet:prev.snippet,source:prev.source,publishedAt:prev.publishedAt,signal_type_candidate:stc,company_name:prev.company_name||null}}];

const items = $input.all();
const results = [];

// Pull the ORIGINAL candidate context for this loop iteration. The Perplexity
// HTTP response carries only { choices }, so url / venture / title / type are
// lost at the HTTP node — reach back to the node that fed the prompt.
function ctxFor() {
  try { const c = $('Perplexity Signal Filter Loop').item; if (c && c.json) return c.json; } catch (e) {}
  try { const c = $('Build Perplexity Prompt').item; if (c && c.json) return c.json; } catch (e) {}
  return {};
}

for (const item of items) {
  let parsed = {
    is_signal: false,
    company_name: null,
    contact_name: null,
    signal_type: null,
    specific_decision: null,
    why_it_matters: null,
    confidence: 'low',
    summary: null,
    signal_score: 0,
    error: null,
  };

  const ctx = ctxFor();
  const choices = item.json && item.json.choices;
  const content = choices && choices[0] && choices[0].message ? choices[0].message.content : null;

  if (!content) {
    parsed.error = 'no_content_from_perplexity';
  } else {
    try {
      const cleaned = content.replace(/```json\s*|\s*```/g, '').trim();
      const obj = JSON.parse(cleaned);
      parsed = Object.assign({}, parsed, obj);

      // Perplexity returns specific_decision + why_it_matters + confidence — NOT
      // summary / signal_score / signal_type. Derive the fields the validity
      // filter, the >=3 score gate, and the zara_signals insert all require.
      // Bug fix 2026-06-11: the old parser left summary/signal_score unset, so
      // the validity check force-failed EVERY real signal -> 0 inserts since Apr.
      if (parsed.is_signal === true) {
        const co = (parsed.company_name || ctx.company_name || '').trim();
        const decision = (parsed.specific_decision || '').trim();
        const why = (parsed.why_it_matters || '').trim();
        parsed.company_name = co || parsed.company_name;
        parsed.summary = [co, decision].filter(Boolean).join(' — ').trim();
        if (parsed.summary.length < 40 && why) {
          parsed.summary = (parsed.summary ? parsed.summary + ' — ' : '') + why;
        }
        const conf = String(parsed.confidence || 'low').toLowerCase();
        parsed.signal_score = conf === 'high' ? 8 : conf === 'medium' ? 5 : 2;
        parsed.signal_type = ctx.signal_type_candidate || parsed.signal_type || 'market-signal';
      }

      // Re-validate AFTER deriving (the old order nuked everything up front).
      if (!parsed.company_name || !parsed.summary || (parsed.summary || '').length < 20 || (parsed.signal_score || 0) < 1) {
        parsed.is_signal = false;
      }
    } catch (e) {
      parsed.error = 'parse_error: ' + e.message;
      parsed.is_signal = false;
    }
  }

  const calCtx = ($('Prepare Context').first() && $('Prepare Context').first().json && $('Prepare Context').first().json.calibrationContext) || '';

  results.push({
    json: Object.assign({}, parsed, {
      venture: ctx.venture || null,
      url: ctx.url || ctx.source_url || null,
      source_url: ctx.url || ctx.source_url || null,
      source_title: ctx.title || null,
      source_published_at: ctx.publishedAt || ctx.published_at || ctx.date || null,
      raw_perplexity_content: content,
      calibration_context: calCtx,
    }),
  });
}

return results;

