const briefRaw = $('Load Agent Brief').first().json;
const briefArr = Array.isArray(briefRaw) ? briefRaw : (briefRaw.data || [briefRaw]);
const brief = briefArr[0]?.brief_content || '';
const identity_prepend = brief ? 'AGENT BRIEF:\n' + brief + '\n\n' : '';

return $input.all().map(item => ({
  json: { ...item.json, identity_prepend }
}));

// Aggregate registry rows into lookup maps; passthrough enrichment for downstream
const rows = $input.all().map(i => i.json).filter(r => r && r.actor_slug);
const apifyRegistry = {};
const apifyInputShapes = {};
for (const r of rows) {
  apifyRegistry[r.task_category] = r.actor_slug;
  if (r.required_input_shape) apifyInputShapes[r.task_category] = r.required_input_shape;
}
return [{ json: { apifyRegistry, apifyInputShapes } }];
